create policy "JAG media readable" on storage.objects for select to anon, authenticated using (bucket_id in ('post-images','post-audio','avatars'));
create policy "JAG upload own folder" on storage.objects for insert to authenticated with check (bucket_id in ('post-images','post-audio','avatars') and (storage.foldername(name))[1] = auth.uid()::text);
create policy "JAG update own files" on storage.objects for update to authenticated using (bucket_id in ('post-images','post-audio','avatars') and (storage.foldername(name))[1] = auth.uid()::text);
create policy "JAG delete own files" on storage.objects for delete to authenticated using (bucket_id in ('post-images','post-audio','avatars') and (storage.foldername(name))[1] = auth.uid()::text);